#!/usr/bin/env bash
# Purpose: re-evaluate selected LongMemEval individual reports with the
# Mem0-style LLM judge prompt for GPT-4o-mini alignment checks.
# Runs: benchmark_longmemeval.task_eval.re_eval_llm_accuracy.
set -euo pipefail

# LongMemEval LLM-judge alignment with the mem0 prompt.
# Evaluation model: gpt-4o-mini-closeai
# Output directories are auto-generated by re_eval_llm_accuracy.py as:
#   <experiment-dir>/reeval_<timestamp>_<eval-model>_mem0
# No --output-dir is passed here, so existing benchmark outputs are not overwritten.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$SCRIPT_DIR"
while [[ "$REPO_ROOT" != "/" && ! -d "$REPO_ROOT/src/mandol" ]]; do
  REPO_ROOT="$(dirname "$REPO_ROOT")"
done
if [[ ! -d "$REPO_ROOT/src/mandol" ]]; then
  echo "Could not locate AgentMemorySystem repo root from $SCRIPT_DIR" >&2
  exit 1
fi
cd "$REPO_ROOT"

mkdir -p nohup_output/longmemeval_mem0_reeval

# 1. GPT-4o-mini dynamic adaptive routed aggressive cascade.
nohup uv run python -m benchmark_longmemeval.task_eval.re_eval_llm_accuracy \
  --data-dir benchmark_longmemeval/task_eval/results/triple_fusion_router_cascade_mad_v3/gpt4o_mini_dynamic_adaptive_routed_aggressive_cascade/individual_reports \
  --model gpt-4o-mini-closeai \
  --llm-judge-prompt mem0 \
  > nohup_output/longmemeval_mem0_reeval/gpt4o_dynamic_adaptive_routed_aggressive_cascade_mem0_gpt4o_mini.log 2>&1 &

# 2. GPT-4.1-mini dynamic adaptive routed aggressive cascade.
nohup uv run python -m benchmark_longmemeval.task_eval.re_eval_llm_accuracy \
  --data-dir benchmark_longmemeval/task_eval/results/triple_fusion_router_cascade_mad_v3/gpt41_mini_dynamic_adaptive_routed_aggressive_cascade/individual_reports \
  --model gpt-4o-mini-closeai \
  --llm-judge-prompt mem0 \
  > nohup_output/longmemeval_mem0_reeval/gpt41_dynamic_adaptive_routed_aggressive_cascade_mem0_gpt4o_mini.log 2>&1 &

# 3. GPT-5 router quantification top50 dynamic adaptive accuracy-first cascade.
nohup uv run python -m benchmark_longmemeval.task_eval.re_eval_llm_accuracy \
  --data-dir benchmark_longmemeval/task_eval/results/ablations/gpt5/eval_gpt4o_mini/router_quantification_top50_dynamic_adaptive_acc_first_routed_aggressive_cascade/individual_reports \
  --model gpt-4o-mini-closeai \
  --llm-judge-prompt mem0 \
  > nohup_output/longmemeval_mem0_reeval/gpt5_router_quantification_top50_dynamic_adaptive_acc_first_mem0_gpt4o_mini.log 2>&1 &

# 4. GPT-5 router top50 aggressive.
nohup uv run python -m benchmark_longmemeval.task_eval.re_eval_llm_accuracy \
  --data-dir benchmark_longmemeval/task_eval/results/ablations/gpt5/eval_gpt4o_mini/router_top50_aggressive_routed_aggressive/individual_reports \
  --model gpt-4o-mini-closeai \
  --llm-judge-prompt mem0 \
  > nohup_output/longmemeval_mem0_reeval/gpt5_router_top50_aggressive_mem0_gpt4o_mini.log 2>&1 &
